package com.javatpoint.servlets;
import java.io.IOException;import javax.servlet.ServletException;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import com.javatpoint.beans.LibrarianBean;import com.javatpoint.dao.LibrarianDao;import com.javatpoint.util.AuthUtil;
@WebServlet("/AddLibrarian") public class AddLibrarian extends HttpServlet{protected void doPost(HttpServletRequest req,HttpServletResponse res)throws ServletException,IOException{if(!AuthUtil.requireAdmin(req,res))return;try{long m=Long.parseLong(req.getParameter("mobile"));if(req.getParameter("password")==null||req.getParameter("password").length()<8){res.sendError(400,"Password must contain at least 8 characters.");return;}LibrarianBean b=new LibrarianBean(req.getParameter("name"),req.getParameter("email"),req.getParameter("password"),m);if(LibrarianDao.save(b)>0)res.sendRedirect("ViewLibrarian");else res.sendError(400,"Unable to create librarian. Check the details and email uniqueness.");}catch(NumberFormatException e){res.sendError(400,"Mobile must contain digits only.");}}}